)

func dial(addr string) (*quic.Conn, *quic.Endpoint) {
 cfg := &quic.Config{TLSConfig: &tls.Config{InsecureSkipVerify: true, MinVersion: tls.VersionTLS13, NextProtos: []string{"perf"}, ServerName: "localhost"}, MaxBidiRemoteStreams: 1000, MaxUniRemoteStreams: 1000, MaxStreamReadBufferSize: 1<<30, MaxConnReadBufferSize: 1<<30, MaxStreamWriteBufferSize: 1<<30}
 ep, err := quic.Listen("udp", "127.0.0.1:0", nil)
 if err!=nil { panic(err)}
 ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second); defer cancel()
 conn, err := ep.Dial(ctx, "udp", addr, cfg)
 if err!=nil { fmt.Println("dial err:",err); os.Exit(1)}
 return conn, ep
}
func main(){
 mode:=os.Args[1]; addr:=os.Args[2]
 conn, ep := dial(addr); defer ep.Close(context.Background())
 st:=conn.ConnectionState(); fmt.Printf("negotiated=%q certs=%d\n", st.NegotiatedProtocol, len(st.PeerCertificates))
 if mode=="streams" {
   typ:=os.Args[3]
   var streams []*quic.Stream
   for i:=0;i<500;i++ {
