     cancel()
     if err!=nil { fmt.Printf("open %d failed: %v\n", i, err); break }
     // Write a byte to actually open on wire? For bi, stream frame maybe only when data/flush.
     s.Write([]byte{0})
     s.Flush()
     streams=append(streams,s)
     if i%10==0 { fmt.Println("opened",i, "id", s.ID())}
   }
   fmt.Println("total opened",len(streams))
   time.Sleep(500*time.Millisecond)
 } else if mode=="request" {
   // args download upload extraHexMode?
   var down uint64=100; var up int=5
   fmt.Sscan(os.Args[3], &down); fmt.Sscan(os.Args[4], &up)
   streamType:=os.Args[5]
   if streamType=="bi" {
     s,err:=conn.NewStream(context.Background()); if err!=nil{panic(err)}
     hdr:=make([]byte,8); binary.BigEndian.PutUint64(hdr, down)
     s.Write(hdr)
     if up>0 { data:=make([]byte,up); for i:=range data{data[i]=42}; s.Write(data)}
     s.CloseWrite()
     fmt.Println("sent bi id",s.ID())
