     s.CloseWrite(); fmt.Println("sent uni id",s.ID())
     ctx,cancel:=context.WithTimeout(context.Background(),3*time.Second); defer cancel()
     rs,err:=conn.AcceptStream(ctx); if err!=nil{fmt.Println("accept err",err); return}
     fmt.Println("accepted response stream id",rs.ID(),"readonly",rs.IsReadOnly())
