	}
	outMu.Lock()
	_, _ = os.Stdout.WriteString(line)
	outMu.Unlock()
}

func printStdout(s string) {
	outMu.Lock()
	_, _ = os.Stdout.WriteString(s)
	outMu.Unlock()
}
