// rustOSError formats an OS error in Rust std::io::Error display style,
// e.g. "Address already in use (os error 98)".
func rustOSError(err error) string {
	if err == nil {
		return ""
	}
	// Unwrap to find an errno.
	var errno uintptr
	var msg string
	cur := err
	for cur != nil {
		type syscallErr interface{ Errno() uintptr }
		// syscall.Errno has an Error method and can be found by string/type.
		if en, ok := asErrno(cur); ok {
			errno = en
			msg = errnoString(en)
			break
		}
		cur = errors.Unwrap(cur)
	}
	if errno != 0 {
		if msg == "" {
			msg = "Unknown error"
		}
		// Capitalize first letter like Rust/glibc strerror strings.
		msg = strings.ToUpper(msg[:1]) + msg[1:]
		return fmt.Sprintf("%s (os error %d)", msg, errno)
	}
	// Fall back to common Go net error substrings.
	s := err.Error()
	// Strip Go's operation prefixes like "listen udp 127.0.0.1:1: bind: ...".
	if idx := strings.LastIndex(s, ": "); idx >= 0 {
		s = s[idx+2:]
	}
	if len(s) > 0 {
		s = strings.ToUpper(s[:1]) + s[1:]
	}
	return s
}

func asErrno(err error) (uintptr, bool) {
	// Avoid importing golang.org/x/sys only for this; use reflection-free
	// matching against syscall.Errno through its concrete behaviour:
	// errors.As with a target of a type implementing error can't name it
	// without syscall, so call a helper in errno_unix.go.
	return extractErrno(err)
}

func errnoString(errno uintptr) string {
	return errnoMessage(errno)
}

// splitHostPortRust is used where we only need host and numeric port after
// our own Rust-like validation.
func splitHostPortLoose(s string) (string, string, bool) {
	h, p, err := net.SplitHostPort(s)
	if err == nil {
		return h, p, true
	}
	idx := strings.LastIndex(s, ":")
	if idx < 0 {
		return s, "", false
	}
	return s[:idx], s[idx+1:], true
}

func canonicalIPString(ip netip.Addr) string {
	return ip.String()
}

