func isKnownOptionToken(tok string, defs []argDef) bool {
	if tok == "--help" || tok == "-h" {
		return true
	}
	if strings.HasPrefix(tok, "--") {
		name := tok[2:]
		if idx := strings.Index(name, "="); idx >= 0 {
			name = name[:idx]
		}
		if name == "help" {
			return true
		}
		for _, d := range defs {
			if d.long == name {
				return true
			}
		}
		return false
	}
	if strings.HasPrefix(tok, "-") && len(tok) > 1 {
		c := tok[1]
		if c == 'h' {
			return true
		}
		for _, d := range defs {
			if d.short != 0 && d.short == c {
