	// For an unknown short cluster, clap names only the first short.
	if strings.HasPrefix(tok, "-") && !strings.HasPrefix(tok, "--") && len(tok) > 2 {
		// Only if first short is unknown; callers pass a normalized token in
		// that case, so leave as-is generally.
	}
	errorWithUsage(bin, usage, fmt.Sprintf("unexpected argument '%s' found", displayTok), tip)
}

