			if seen[d.long] {
				usage := usageServer(bin)
				if command == "client" { usage = usageClient(bin) }
				errorWithUsage(bin, usage, fmt.Sprintf("the argument '%s' cannot be used multiple times", argDisplay(*d)), "")
			}
			var raw string
			if len(tok) > 2 {
				raw = tok[2:]
				if strings.HasPrefix(raw, "=") {
					raw = raw[1:]
				}
				if raw == "" {
					missingValueError(*d)
				}
			} else {
				if i >= len(args) {
					missingValueError(*d)
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					if next == "--" || isKnownOptionToken(next, defs) {
						missingValueError(*d)
					}
					unexpectedArgument(bin, command, next, defs)
				}
				raw = next
				i++
			}
			var err error
			if command == "server" {
				err = applyValue(command, server, nil, *d, raw)
			} else {
				err = applyValue(command, nil, client, *d, raw)
			}
			if err != nil {
				invalidValueError(bin, *d, raw, err)
			}
			seen[d.long] = true
			seenOrder = append(seenOrder, *d)
			continue
		}
		// Positional.
		if command == "server" {
			unexpectedArgument(bin, command, tok, defs)
		}
		if hostSet {
			unexpectedArgument(bin, command, tok, defs)
		}
		client.Host = tok
		hostSet = true
	}

	if command == "server" {
		// key/cert require each other.
		if (server.Key == nil) != (server.Cert == nil) {
			var missing argDef
			var provided argDef
			for _, d := range defs {
				if d.long == "key" && server.Key != nil { provided = d }
				if d.long == "cert" && server.Cert != nil { provided = d }
				if d.long == "key" && server.Key == nil { missing = d }
				if d.long == "cert" && server.Cert == nil { missing = d }
			}
			// usage: provided pair member first, missing second, then other
			// used arguments in declaration order.
			parts := []string{argDisplay(provided), argDisplay(missing)}
			for _, d := range defs {
				if d.long == provided.long || d.long == missing.long {
					continue
				}
				if seen[d.long] {
					parts = append(parts, argDisplay(d))
				}
			}
			usage := fmt.Sprintf("%s server %s", bin, strings.Join(parts, " "))
			var b strings.Builder
			b.WriteString("error: the following required arguments were not provided:\n")
			b.WriteString(fmt.Sprintf("  %s\n", argDisplay(missing)))
			b.WriteString(fmt.Sprintf("\nUsage: %s\n\nFor more information, try '--help'.\n", usage))
			clapError(b.String())
		}
		return parseResult{command: command, server: server}
	}
	return parseResult{command: command, client: client}
}

func unrecognizedSubcommand(bin, tok string, candidates []string, usage string, includeForMore bool) {
	tip := ""
	if sug := suggest(tok, candidates); sug != "" {
		tip = fmt.Sprintf("a similar subcommand exists: '%s'", sug)
	}
	var b strings.Builder
	b.WriteString(fmt.Sprintf("error: unrecognized subcommand '%s'\n", tok))
	if tip != "" {
		b.WriteString(fmt.Sprintf("\n  tip: %s\n", tip))
	}
	b.WriteString(fmt.Sprintf("\nUsage: %s\n", usage))
	if includeForMore {
		b.WriteString("\nFor more information, try '--help'.\n")
	}
	_ = bin
	clapError(b.String())
}

func parseCLI() parseResult {
	bin := binName()
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Fprint(os.Stderr, renderHelp(rootHelpTemplate, bin))
		os.Exit(2)
	}
	first := args[0]
	// Root short/long help: any cluster starting with h after '-'.
	if first == "--help" || first == "-h" || (strings.HasPrefix(first, "-") && !strings.HasPrefix(first, "--") && len(first) > 1 && first[1] == 'h') {
		fmt.Fprint(os.Stdout, renderHelp(rootHelpTemplate, bin))
		os.Exit(0)
	}
	if first == "--" {
		if len(args) > 1 {
			tok := args[1]
			tip := ""
			if tok == "server" || tok == "client" || tok == "help" {
				tip = fmt.Sprintf("subcommand '%s' exists; to use it, remove the '--' before it", tok)
			}
			errorWithUsage(bin, usageRoot(bin), fmt.Sprintf("unexpected argument '%s' found", tok), tip)
		}
		// A lone "--" with no subcommand: clap falls back to help error.
		fmt.Fprint(os.Stderr, renderHelp(rootHelpTemplate, bin))
		os.Exit(2)
	}
	if first == "help" {
		rest := args[1:]
		if len(rest) == 0 {
			fmt.Fprint(os.Stdout, renderHelp(rootHelpTemplate, bin))
			os.Exit(0)
		}
		switch rest[0] {
		case "server":
			if len(rest) > 1 {
				unrecognizedSubcommand(bin, rest[1], nil, usageServer(bin), true)
			}
			fmt.Fprint(os.Stdout, renderHelp(serverLongHelpTemplate, bin))
			os.Exit(0)
		case "client":
			if len(rest) > 1 {
				unrecognizedSubcommand(bin, rest[1], nil, usageClient(bin), true)
			}
			fmt.Fprint(os.Stdout, renderHelp(clientLongHelpTemplate, bin))
			os.Exit(0)
		case "help":
			if len(rest) > 1 {
				// Clap emits no "For more information" line for this one.
				var b strings.Builder
				b.WriteString(fmt.Sprintf("error: unrecognized subcommand '%s'\n\nUsage: %s help [COMMAND]...\n", rest[1], bin))
				clapError(b.String())
			}
			fmt.Fprint(os.Stdout, renderHelp(helpHelpTemplate, bin))
			os.Exit(0)
		default:
			unrecognizedSubcommand(bin, rest[0], []string{"server", "client", "help"}, usageRoot(bin), true)
		}
	}
	if first == "server" || first == "client" {
		return parseSubcommand(bin, first, args[1:])
	}
	if strings.HasPrefix(first, "-") && first != "-" {
		// Unknown root argument.
		if strings.HasPrefix(first, "--") {
			unexpectedArgument(bin, "", first, nil)
		}
		// unknown short: name only first
		unexpectedArgument(bin, "", "-"+string(first[1]), nil)
	}
	unrecognizedSubcommand(bin, first, []string{"server", "client", "help"}, usageRoot(bin), true)
	// unreachable
	return parseResult{}
}
EOF
gofmt -w cli.go"}

