		return applyCommon(&client.Common, d.long, raw, d.kind)
	}
	return nil
}

var errMissingValue = fmt.Errorf("missing value")

func invalidValueError(bin string, d argDef, raw string, err error) {
	if err == errMissingValue {
		missingValueError(d)
		return
	}
	if d.kind == kindCongestion {
		// raw was validated before this point for non-empty values.
		errorNoUsage(fmt.Sprintf("invalid value '%s' for '%s'\n  [possible values: cubic, bbr, new-reno]", raw, argDisplay(d)), "")
		return
	}
	errorNoUsage(fmt.Sprintf("invalid value '%s' for '%s': %s", raw, argDisplay(d), err.Error()), "")
	_ = bin
}

func missingValueError(d argDef) {
	extra := ""
	if d.kind == kindCongestion {
		extra = "  [possible values: cubic, bbr, new-reno]\n"
	}
	errorNoUsage(fmt.Sprintf("a value is required for '%s' but none was supplied", argDisplay(d)), extra)
}

func isKnownOptionToken(tok string, defs []argDef) bool {
	if tok == "--help" || tok == "-h" {
		return true
	}
	if strings.HasPrefix(tok, "--") {
		name := tok[2:]
		if idx := strings.Index(name, "="); idx >= 0 {
			name = name[:idx]
		}
		if name == "help" {
			return true
		}
		for _, d := range defs {
			if d.long == name {
				return true
			}
		}
		return false
	}
	if strings.HasPrefix(tok, "-") && len(tok) > 1 {
		c := tok[1]
		if c == 'h' {
			return true
		}
		for _, d := range defs {
			if d.short != 0 && d.short == c {
				return true
			}
		}
	}
	return false
}

func unexpectedArgument(bin, command, tok string, defs []argDef) {
	usage := usageRoot(bin)
	if command == "server" {
		usage = usageServer(bin)
	} else if command == "client" {
		usage = usageClient(bin)
	}
	tip := ""
	// Long-option suggestion.
	if strings.HasPrefix(tok, "--") {
		name := tok[2:]
		if idx := strings.Index(name, "="); idx >= 0 {
			name = name[:idx]
		}
		candidates := []string{"help"}
		for _, d := range defs {
			candidates = append(candidates, d.long)
		}
		if sug := suggest(name, candidates); sug != "" {
			tip = fmt.Sprintf("a similar argument exists: '--%s'", sug)
			// Build suggested usage.
			if command == "" {
				if sug == "help" {
					usage = fmt.Sprintf("%s --help <COMMAND>", bin)
				}
			} else {
				for _, d := range defs {
					if d.long == sug {
						if command == "server" {
							usage = fmt.Sprintf("%s server %s", bin, argDisplay(d))
						} else {
							usage = fmt.Sprintf("%s client %s [HOST]", bin, argDisplay(d))
						}
						break
					}
				}
				if sug == "help" {
					if command == "server" {
						usage = fmt.Sprintf("%s server --help", bin)
					} else if command == "client" {
						usage = fmt.Sprintf("%s client --help [HOST]", bin)
					}
				}
			}
		}
	}
	if tip == "" && command == "client" && strings.HasPrefix(tok, "-") && tok != "-" {
		tip = fmt.Sprintf("to pass '%s' as a value, use '-- %s'", tok, tok)
	}
	displayTok := tok
	// For an unknown short cluster, clap names only the first short.
	if strings.HasPrefix(tok, "-") && !strings.HasPrefix(tok, "--") && len(tok) > 2 {
		// Only if first short is unknown; callers pass a normalized token in
		// that case, so leave as-is generally.
	}
	errorWithUsage(bin, usage, fmt.Sprintf("unexpected argument '%s' found", displayTok), tip)
}

func parseSubcommand(bin, command string, args []string) parseResult {
	var defs []argDef
	var server *ServerOpts
	var client *ClientOpts
	if command == "server" {
		defs = serverDefs()
		listen, _ := parseSocketAddr("[::]:4433")
		server = &ServerOpts{Listen: listen, Common: defaultCommon()}
	} else {
		defs = clientDefs()
		client = &ClientOpts{Host: "localhost:4433", BiRequests: 1, DownloadSize: 1024 * 1024, UploadSize: 1024 * 1024, Duration: 60, Interval: 1, Common: defaultCommon()}
	}
	findLong := func(name string) *argDef {
		for i := range defs {
			if defs[i].long == name {
				return &defs[i]
			}
		}
		return nil
	}
	findShort := func(c byte) *argDef {
		for i := range defs {
			if defs[i].short != 0 && defs[i].short == c {
				return &defs[i]
			}
		}
		return nil
	}
	seen := map[string]bool{}
	var seenOrder []argDef // in command order, for required-pair usage
	positionalOnly := false
	hostSet := false

	printHelp := func(long bool) {
		if command == "server" {
			if long {
				fmt.Fprint(os.Stdout, renderHelp(serverLongHelpTemplate, bin))
			} else {
				fmt.Fprint(os.Stdout, renderHelp(serverShortHelpTemplate, bin))
			}
		} else {
			if long {
				fmt.Fprint(os.Stdout, renderHelp(clientLongHelpTemplate, bin))
			} else {
				fmt.Fprint(os.Stdout, renderHelp(clientShortHelpTemplate, bin))
			}
		}
		os.Exit(0)
	}

	i := 0
	for i < len(args) {
		tok := args[i]
		i++
		if !positionalOnly && tok == "--" {
			positionalOnly = true
			continue
		}
		if !positionalOnly && tok == "--help" {
			printHelp(true)
		}
		if !positionalOnly && tok == "-h" {
			printHelp(false)
		}
		if !positionalOnly && strings.HasPrefix(tok, "--") {
			nameVal := tok[2:]
			name := nameVal
			inlineVal := ""
			hasInline := false
			if idx := strings.Index(nameVal, "="); idx >= 0 {
				name = nameVal[:idx]
				inlineVal = nameVal[idx+1:]
				hasInline = true
			}
			d := findLong(name)
			if d == nil {
				unexpectedArgument(bin, command, tok, defs)
			}
			if d.kind == kindBool {
				if hasInline {
					usage := ""
					if command == "server" {
						usage = fmt.Sprintf("%s server %s", bin, argDisplay(*d))
					} else {
						usage = fmt.Sprintf("%s client %s", bin, argDisplay(*d))
						// client bool usage in clap includes the specific flag only
					}
					errorWithUsage(bin, usage, fmt.Sprintf("unexpected value '%s' for '--%s' found; no more were expected", inlineVal, d.long), "")
				}
				if seen[d.long] {
					usage := usageServer(bin)
					if command == "client" { usage = usageClient(bin) }
					errorWithUsage(bin, usage, fmt.Sprintf("the argument '%s' cannot be used multiple times", argDisplay(*d)), "")
				}
				seen[d.long] = true
				seenOrder = append(seenOrder, *d)
				// Apply bool through applyValue with empty raw.
				if command == "server" {
					_ = applyCommon(&server.Common, d.long, "", d.kind)
				} else {
					_ = applyCommon(&client.Common, d.long, "", d.kind)
				}
				continue
			}
			// option with a value
			if seen[d.long] {
				usage := usageServer(bin)
				if command == "client" { usage = usageClient(bin) }
				errorWithUsage(bin, usage, fmt.Sprintf("the argument '%s' cannot be used multiple times", argDisplay(*d)), "")
			}
			var raw string
			if hasInline {
				raw = inlineVal
				if (d.kind == kindPath || d.kind == kindCongestion) && raw == "" {
					missingValueError(*d)
				}
			} else {
				if i >= len(args) {
					missingValueError(*d)
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					if next == "--" || isKnownOptionToken(next, defs) {
						missingValueError(*d)
					}
					// Unknown option: clap reports it instead.
					unexpectedArgument(bin, command, next, defs)
				}
				raw = next
				i++
			}
			if d.kind == kindCongestion {
				if raw == "" {
					missingValueError(*d)
				}
				if raw != "cubic" && raw != "bbr" && raw != "new-reno" {
					invalidValueError(bin, *d, raw, fmt.Errorf("invalid"))
				}
			}
			var err error
			if command == "server" {
				err = applyValue(command, server, nil, *d, raw)
			} else {
				err = applyValue(command, nil, client, *d, raw)
			}
			if err != nil {
				invalidValueError(bin, *d, raw, err)
			}
			seen[d.long] = true
			seenOrder = append(seenOrder, *d)
			continue
		}
		if !positionalOnly && strings.HasPrefix(tok, "-") && tok != "-" {
			// Short cluster. First character decides.
			c := tok[1]
			if c == 'h' {
				printHelp(false)
			}
			d := findShort(c)
			if d == nil {
				unexpectedArgument(bin, command, "-"+string(c), defs)
			}
			// d expects a value (only -k/-c exist besides -h).
			if seen[d.long] {
				usage := usageServer(bin)
				if command == "client" { usage = usageClient(bin) }
				errorWithUsage(bin, usage, fmt.Sprintf("the argument '%s' cannot be used multiple times", argDisplay(*d)), "")
			}
			var raw string
			if len(tok) > 2 {
				raw = tok[2:]
				if strings.HasPrefix(raw, "=") {
					raw = raw[1:]
				}
				if raw == "" {
					missingValueError(*d)
				}
			} else {
				if i >= len(args) {
					missingValueError(*d)
				}
				next := args[i]
				if next != "-" && strings.HasPrefix(next, "-") && len(next) > 1 {
					if next == "--" || isKnownOptionToken(next, defs) {
						missingValueError(*d)
					}
					unexpectedArgument(bin, command, next, defs)
				}
				raw = next
				i++
			}
			var err error
			if command == "server" {
				err = applyValue(command, server, nil, *d, raw)
			} else {
				err = applyValue(command, nil, client, *d, raw)
			}
			if err != nil {
				invalidValueError(bin, *d, raw, err)
			}
			seen[d.long] = true
			seenOrder = append(seenOrder, *d)
			continue
		}
		// Positional.
		if command == "server" {
			unexpectedArgument(bin, command, tok, defs)
		}
		if hostSet {
			unexpectedArgument(bin, command, tok, defs)
		}
		client.Host = tok
		hostSet = true
	}

	if command == "server" {
		// key/cert require each other.
		if (server.Key == nil) != (server.Cert == nil) {
			var missing argDef
			var provided argDef
			for _, d := range defs {
				if d.long == "key" && server.Key != nil { provided = d }
				if d.long == "cert" && server.Cert != nil { provided = d }
				if d.long == "key" && server.Key == nil { missing = d }
				if d.long == "cert" && server.Cert == nil { missing = d }
			}
			// usage: provided pair member first, missing second, then other
			// used arguments in declaration order.
			parts := []string{argDisplay(provided), argDisplay(missing)}
			for _, d := range defs {
				if d.long == provided.long || d.long == missing.long {
					continue
				}
				if seen[d.long] {
					parts = append(parts, argDisplay(d))
				}
			}
			usage := fmt.Sprintf("%s server %s", bin, strings.Join(parts, " "))
			var b strings.Builder
			b.WriteString("error: the following required arguments were not provided:\n")
			b.WriteString(fmt.Sprintf("  %s\n", argDisplay(missing)))
			b.WriteString(fmt.Sprintf("\nUsage: %s\n\nFor more information, try '--help'.\n", usage))
			clapError(b.String())
		}
		return parseResult{command: command, server: server}
	}
	return parseResult{command: command, client: client}
}

func unrecognizedSubcommand(bin, tok string, candidates []string, usage string, includeForMore bool) {
	tip := ""
	if sug := suggest(tok, candidates); sug != "" {
		tip = fmt.Sprintf("a similar subcommand exists: '%s'", sug)
	}
	var b strings.Builder
	b.WriteString(fmt.Sprintf("error: unrecognized subcommand '%s'\n", tok))
	if tip != "" {
		b.WriteString(fmt.Sprintf("\n  tip: %s\n", tip))
	}
	b.WriteString(fmt.Sprintf("\nUsage: %s\n", usage))
	if includeForMore {
		b.WriteString("\nFor more information, try '--help'.\n")
	}
	_ = bin
	clapError(b.String())
}

func parseCLI() parseResult {
	bin := binName()
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Fprint(os.Stderr, renderHelp(rootHelpTemplate, bin))
		os.Exit(2)
	}
	first := args[0]
	// Root short/long help: any cluster starting with h after '-'.
	if first == "--help" || first == "-h" || (strings.HasPrefix(first, "-") && !strings.HasPrefix(first, "--") && len(first) > 1 && first[1] == 'h') {
		fmt.Fprint(os.Stdout, renderHelp(rootHelpTemplate, bin))
		os.Exit(0)
	}
	if first == "--" {
		if len(args) > 1 {
			tok := args[1]
			tip := ""
			if tok == "server" || tok == "client" || tok == "help" {
				tip = fmt.Sprintf("subcommand '%s' exists; to use it, remove the '--' before it", tok)
			}
			errorWithUsage(bin, usageRoot(bin), fmt.Sprintf("unexpected argument '%s' found", tok), tip)
		}
		// A lone "--" with no subcommand: clap falls back to help error.
		fmt.Fprint(os.Stderr, renderHelp(rootHelpTemplate, bin))
		os.Exit(2)
	}
	if first == "help" {
		rest := args[1:]
		if len(rest) == 0 {
			fmt.Fprint(os.Stdout, renderHelp(rootHelpTemplate, bin))
			os.Exit(0)
		}
		switch rest[0] {
		case "server":
			if len(rest) > 1 {
				unrecognizedSubcommand(bin, rest[1], nil, usageServer(bin), true)
			}
			fmt.Fprint(os.Stdout, renderHelp(serverLongHelpTemplate, bin))
			os.Exit(0)
		case "client":
			if len(rest) > 1 {
				unrecognizedSubcommand(bin, rest[1], nil, usageClient(bin), true)
			}
			fmt.Fprint(os.Stdout, renderHelp(clientLongHelpTemplate, bin))
			os.Exit(0)
		case "help":
			if len(rest) > 1 {
				// Clap emits no "For more information" line for this one.
				var b strings.Builder
				b.WriteString(fmt.Sprintf("error: unrecognized subcommand '%s'\n\nUsage: %s help [COMMAND]...\n", rest[1], bin))
				clapError(b.String())
			}
			fmt.Fprint(os.Stdout, renderHelp(helpHelpTemplate, bin))
			os.Exit(0)
		default:
			unrecognizedSubcommand(bin, rest[0], []string{"server", "client", "help"}, usageRoot(bin), true)
		}
	}
	if first == "server" || first == "client" {
		return parseSubcommand(bin, first, args[1:])
	}
	if strings.HasPrefix(first, "-") && first != "-" {
		// Unknown root argument.
		if strings.HasPrefix(first, "--") {
			unexpectedArgument(bin, "", first, nil)
		}
		// unknown short: name only first
		unexpectedArgument(bin, "", "-"+string(first[1]), nil)
	}
	unrecognizedSubcommand(bin, first, []string{"server", "client", "help"}, usageRoot(bin), true)
	// unreachable
	return parseResult{}
}
