func binName() string {
	if len(os.Args) == 0 || os.Args[0] == "" {
		return "executable"
	}
	b := filepath.Base(os.Args[0])
	if b == "." || b == "/" || b == "" {
		return os.Args[0]
	}
	return b
}

func usageRoot(bin string) string { return fmt.Sprintf("%s <COMMAND>", bin) }
func usageServer(bin string) string { return fmt.Sprintf("%s server [OPTIONS]", bin) }
func usageClient(bin string) string { return fmt.Sprintf("%s client [OPTIONS] [HOST]", bin) }

func printToStderrAndExit(text string, code int) {
	fmt.Fprint(os.Stderr, text)
	os.Exit(code)
}

func clapError(text string) {
	printToStderrAndExit(text, 2)
}

func errorWithUsage(bin, usage, first string, tip string) {
	var b strings.Builder
	b.WriteString("error: ")
	b.WriteString(first)
	b.WriteString("\n")
	if tip != "" {
		b.WriteString("\n  tip: ")
		b.WriteString(tip)
		b.WriteString("\n")
	}
	b.WriteString("\nUsage: ")
	b.WriteString(usage)
	b.WriteString("\n\nFor more information, try '--help'.\n")
	_ = bin
	clapError(b.String())
}

func errorNoUsage(first string, extra string) {
	var b strings.Builder
	b.WriteString("error: ")
	b.WriteString(first)
	b.WriteString("\n")
	if extra != "" {
		b.WriteString(extra)
	}
	b.WriteString("\nFor more information, try '--help'.\n")
	clapError(b.String())
}

func argDisplay(d argDef) string {
	if d.valueName == "" {
		return "--" + d.long
	}
	return fmt.Sprintf("--%s <%s>", d.long, d.valueName)
}

// Jaro-Winkler similarity, used to approximate clap's suggestions.
func jaroWinkler(a, b string) float64 {
	ja := jaro(a, b)
	prefix := 0
	for prefix < len(a) && prefix < len(b) && prefix < 4 && a[prefix] == b[prefix] {
		prefix++
	}
	return ja + float64(prefix)*0.1*(1-ja)
}

func jaro(a, b string) float64 {
	if a == b {
		return 1
	}
	la, lb := len(a), len(b)
	if la == 0 || lb == 0 {
		return 0
	}
	matchDistance := max(la, lb)/2 - 1
	if matchDistance < 0 {
		matchDistance = 0
	}
	aMatches := make([]bool, la)
	bMatches := make([]bool, lb)
	matches := 0
	for i := 0; i < la; i++ {
		start := max(0, i-matchDistance)
		end := min(i+matchDistance+1, lb)
		for j := start; j < end; j++ {
			if !bMatches[j] && a[i] == b[j] {
				aMatches[i] = true
				bMatches[j] = true
				matches++
				break
			}
		}
	}
	if matches == 0 {
		return 0
	}
	t := 0
	k := 0
	for i := 0; i < la; i++ {
		if !aMatches[i] {
			continue
		}
		for !bMatches[k] {
			k++
		}
		if a[i] != b[k] {
			t++
		}
		k++
	}
	m := float64(matches)
	return (m/float64(la) + m/float64(lb) + (m-float64(t)/2)/m) / 3
}

func suggest(name string, candidates []string) string {
	best := ""
	bestScore := 0.0
	for _, c := range candidates {
		s := jaroWinkler(name, c)
		if s > bestScore {
			bestScore = s
			best = c
		}
	}
	if bestScore > 0.8 {
		return best
	}
	return ""
}

