		case "key":
			v := raw
			server.Key = &v
			return nil
		case "cert":
			v := raw
			server.Cert = &v
			return nil
		}
		return applyCommon(&server.Common, d.long, raw, d.kind)
	}
	switch d.long {
	case "ip":
		v, err := parseIPAddress(raw)
		if err != nil { return err }
		client.IP = &v
	case "local-addr":
		v, err := parseSocketAddr(raw)
		if err != nil { return err }
		client.LocalAddr = &v
	case "uni-requests":
		v, err := parseRustU64(raw)
		if err != nil { return err }
		client.UniRequests = v
	case "bi-requests":
		v, err := parseRustU64(raw)
