package main

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"os"
	"strings"
)

type pemItem struct {
	tag  string
	data []byte
}

func rustIOErrorString(err error) string {
	return rustOSError(err)
}

// readFileRust opens and reads, distinguishing the open from the read stage
// so callers can mirror the reference's two certificate contexts.
func readFileStages(path string) (data []byte, openErr error, readErr error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err, nil
	}
	defer f.Close()
	var buf bytes.Buffer
	tmp := make([]byte, 8192)
	for {
		n, err := f.Read(tmp)
		if n > 0 {
			buf.Write(tmp[:n])
		}
		if err != nil {
			if err.Error() == "EOF" {
				break
			}
			return nil, nil, err
		}
		if n == 0 {
			break
		}
	}
	return buf.Bytes(), nil, nil
}

func pemErrorMissingEnd(tag string) error {
	parts := make([]string, len(tag))
	for i := 0; i < len(tag); i++ {
		parts[i] = fmt.Sprintf("%d", tag[i])
	}
	return fmt.Errorf("missing section end marker: [%s]", strings.Join(parts, ", "))
}

// scanPEMItems walks all PEM blocks in order, validating each block's
// base64, in the style of the PEM iterator used by the reference.
// It stops at (and includes) the first item whose tag is in stopAt, if
// stopAt is non-empty, mirroring a "first key" search.
func scanPEMItems(data []byte, stopAt map[string]bool) ([]pemItem, error) {
	var items []pemItem
	rest := data
	for {
		idx := bytes.Index(rest, []byte("-----BEGIN "))
		if idx < 0 {
			return items, nil
		}
		rest = rest[idx+len("-----BEGIN "):]
		endTag := bytes.Index(rest, []byte("-----"))
		if endTag < 0 {
			// A BEGIN line with no closing dashes on the line is not
			// treated as a section by pem parsers; keep scanning.
			continue
		}
		tag := string(rest[:endTag])
		rest = rest[endTag+len("-----"):]
		// tag must be nonempty and without newlines to be a section.
		if tag == "" || strings.ContainsAny(tag, "\r\n") {
			continue
		}
		endMarker := []byte("-----END " + tag + "-----")
		endIdx := bytes.Index(rest, endMarker)
		if endIdx < 0 {
			return nil, pemErrorMissingEnd(tag)
		}
		body := rest[:endIdx]
		rest = rest[endIdx+len(endMarker):]
		decoded, err := decodePEMBody(body)
		if err != nil {
			return nil, err
		}
		items = append(items, pemItem{tag: tag, data: decoded})
		if len(stopAt) > 0 && stopAt[tag] {
			return items, nil
		}
	}
}

func decodePEMBody(body []byte) ([]byte, error) {
	// Drop possible PEM headers (lines containing ':' before a blank line)
	// such as Proc-Type in legacy keys, plus all whitespace.
	var cleaned []byte
	lines := bytes.Split(body, []byte("\n"))
	inHeaders := true
	for _, line := range lines {
		trimmed := bytes.TrimSpace(line)
		if len(trimmed) == 0 {
			inHeaders = false
			continue
		}
		if inHeaders && bytes.Contains(trimmed, []byte(":")) {
			continue
		}
		inHeaders = false
		for _, c := range trimmed {
			if c == ' ' || c == '\t' || c == '\r' {
				continue
			}
			cleaned = append(cleaned, c)
		}
	}
	// Validate characters in scan order to mirror base64 decode errors.
	for _, c := range cleaned {
		ok := (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '='
		if !ok {
			return nil, fmt.Errorf("base64 decode error: InvalidCharacter(%d)", c)
		}
	}
	decoded, err := base64.StdEncoding.DecodeString(string(cleaned))
	if err != nil {
		// Determine a plausible rustls-pemfile-style message.
		msg := err.Error()
		if strings.Contains(msg, "illegal base64 data at input byte") {
			// Character validation above handled most of these.
			return nil, fmt.Errorf("base64 decode error: InvalidLength")
		}
		return nil, fmt.Errorf("base64 decode error: InvalidLength")
	}
	return decoded, nil
}

// readPrivateKeyPEM mirrors a search for the first private-key item.
func readPrivateKeyPEM(path string) (tag string, der []byte, err error) {
	data, openErr, readErr := readFileStages(path)
	if openErr != nil {
		return "", nil, fmt.Errorf("reading private key: I/O error: %s", rustIOErrorString(openErr))
	}
	if readErr != nil {
		return "", nil, fmt.Errorf("reading private key: I/O error: %s", rustIOErrorString(readErr))
	}
	keyTags := map[string]bool{"PRIVATE KEY": true, "RSA PRIVATE KEY": true, "EC PRIVATE KEY": true}
	items, err := scanPEMItems(data, keyTags)
	if err != nil {
		return "", nil, fmt.Errorf("reading private key: %s", err.Error())
	}
	for _, it := range items {
		if keyTags[it.tag] {
			return it.tag, it.data, nil
		}
	}
	return "", nil, fmt.Errorf("reading private key: no items found")
}

// readCertChainPEM mirrors collecting all CERTIFICATE items.
func readCertChainPEM(path string) ([][]byte, error) {
	data, openErr, readErr := readFileStages(path)
	if openErr != nil {
		return nil, fmt.Errorf("reading certificate chain file: I/O error: %s", rustIOErrorString(openErr))
	}
	if readErr != nil {
		return nil, fmt.Errorf("reading certificate chain: I/O error: %s", rustIOErrorString(readErr))
	}
	items, err := scanPEMItems(data, nil)
	if err != nil {
		return nil, fmt.Errorf("reading certificate chain: %s", err.Error())
	}
	var certs [][]byte
	for _, it := range items {
		if it.tag == "CERTIFICATE" {
			certs = append(certs, it.data)
		}
	}
	return certs, nil
}
EOF
