func rustPanic(location string, value string) {
	fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at %s:\ncalled `Result::unwrap()` on an `Err` value: %s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", os.Getpid(), location, value)
	os.Exit(101)
}

func parseAnyPrivateKey(der []byte) (crypto.Signer, bool) {
	if k, err := x509.ParsePKCS8PrivateKey(der); err == nil {
		if s, ok := k.(crypto.Signer); ok {
			switch s.Public().(type) {
			case *rsa.PublicKey, *ecdsa.PublicKey, ed25519.PublicKey:
				return s, true
			}
		}
		return nil, false
	}
	if k, err := x509.ParsePKCS1PrivateKey(der); err == nil {
		return k, true
	}
	if k, err := x509.ParseECPrivateKey(der); err == nil {
		return k, true
	}
	return nil, false
}

func publicKeysEqual(a, b crypto.PublicKey) bool {
	ad, err1 := x509.MarshalPKIXPublicKey(a)
	bd, err2 := x509.MarshalPKIXPublicKey(b)
	return err1 == nil && err2 == nil && bytes.Equal(ad, bd)
}

// loadServerCertificate loads a key/cert pair, reproducing the reference's
// file errors and its panics on a semantically invalid pair.
func loadServerCertificate(keyPath, certPath string) (tls.Certificate, error) {
	_, keyDER, err := readPrivateKeyPEM(keyPath)
	if err != nil {
		return tls.Certificate{}, err
	}
	certDERs, err := readCertChainPEM(certPath)
	if err != nil {
		return tls.Certificate{}, err
	}
	priv, ok := parseAnyPrivateKey(keyDER)
	if !ok {
		rustPanic("/workspace/perf/src/server.rs:58:10", "General(\"failed to parse private key as RSA, ECDSA, or EdDSA\")")
	}
	if len(certDERs) == 0 {
		rustPanic("/workspace/perf/src/server.rs:58:10", "NoCertificatesPresented")
	}
	var leaf *x509.Certificate
	for i, der := range certDERs {
		c, err := x509.ParseCertificate(der)
		if err != nil {
			rustPanic("/workspace/perf/src/server.rs:58:10", "InvalidCertificate(BadEncoding)")
		}
		if i == 0 {
			leaf = c
		}
	}
	if leaf == nil || !publicKeysEqual(leaf.PublicKey, priv.Public()) {
		rustPanic("/workspace/perf/src/server.rs:58:10", "InconsistentKeys(KeyMismatch)")
	}
	return tls.Certificate{Certificate: certDERs, PrivateKey: priv, Leaf: leaf}, nil
}

func generateSelfSigned() (tls.Certificate, error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return tls.Certificate{}, err
	}
	// The reference's self-signed certificates carry a large random serial.
	serialBytes := make([]byte, 19)
	if _, err := rand.Read(serialBytes); err != nil {
		return tls.Certificate{}, err
	}
	serialBytes[0] &= 0x3f // keep to roughly 148 bits and positive
	serial := new(big.Int).SetBytes(serialBytes)
	if serial.Sign() == 0 {
		serial.SetInt64(1)
	}
	tmpl := &x509.Certificate{
		SerialNumber: serial,
		Subject:      pkix.Name{CommonName: "rcgen self signed cert"},
		DNSNames:     []string{"localhost"},
		NotBefore:    time.Date(1975, 1, 1, 0, 0, 0, 0, time.UTC),
		NotAfter:     time.Date(4096, 1, 1, 0, 0, 0, 0, time.UTC),
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		return tls.Certificate{}, err
	}
	leaf, _ := x509.ParseCertificate(der)
	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key, Leaf: leaf}, nil
}

// openKeylog returns a writer for TLS key logging, or nil if disabled or
// the file cannot be opened (matching rustls's silent no-op behaviour).
func openKeylog(enabled bool) *os.File {
	if !enabled {
		return nil
	}
	path := os.Getenv("SSLKEYLOGFILE")
	if path == "" {
		return nil
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0666)
	if err != nil {
		return nil
	}
	return f
}
