package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"sync"
	"time"
)

// A small qlog writer that translates the QUIC library's slog-based qlog
// records into the JSON-SEQ shape the reference emits: packet sent /
// received events with a compact header, and recovery metrics updates.

type qlogWriter struct {
	mu      sync.Mutex
	f       *os.File
	start   time.Time
	title   string
	closed  bool
}

func createQlog(path string, isServer bool) (*qlogWriter, error) {
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	title := "perf-client"
	if isServer {
		title = "perf-server"
	}
	w := &qlogWriter{f: f, start: time.Now(), title: title}
	header := fmt.Sprintf("\x1e{\"qlog_version\":\"0.3\",\"qlog_format\":\"JSON-SEQ\",\"title\":\"%s\",\"trace\":{\"vantage_point\":{\"type\":\"unknown\"},\"title\":\"%s\",\"configuration\":{\"time_offset\":0.0}}}\n", title, title)
	_, _ = f.WriteString(header)
	return w, nil
}

func (w *qlogWriter) Close() {
	if w == nil {
		return
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if !w.closed {
		w.closed = true
		_ = w.f.Close()
	}
}

func (w *qlogWriter) logger() *slog.Logger {
	if w == nil {
		return nil
	}
	return slog.New(&qlogHandler{w: w})
}

type qlogHandler struct {
	w       *qlogWriter
	groupID string
	attrs   []slog.Attr
	group   string
}

func (h *qlogHandler) Enabled(ctx context.Context, level slog.Level) bool {
	// Accept even the most verbose (per-frame) records.
	return true
}

func (h *qlogHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	nh := *h
	nh.attrs = append(append([]slog.Attr{}, h.attrs...), attrs...)
	for _, a := range attrs {
		if a.Key == "group_id" {
			nh.groupID = a.Value.String()
		}
	}
	return &nh
}

func (h *qlogHandler) WithGroup(name string) slog.Handler {
	nh := *h
	nh.group = name
	return &nh
}

// attrMap flattens a record's attributes (including groups) into nested maps.
func attrValue(v slog.Value) interface{} {
	switch v.Kind() {
	case slog.KindGroup:
		m := map[string]interface{}{}
		for _, a := range v.Group() {
			m[a.Key] = attrValue(a.Value)
		}
		return m
	case slog.KindDuration:
