{"command":"cat > stats.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"math/big"
	"sort"
	"strings"
	"sync"
	"time"
)

// ---- duration and throughput formatting ----

func formatDuration(d time.Duration) string {
	ns := d.Nanoseconds()
	switch {
	case d >= time.Second:
		return fmt.Sprintf("%.2fs", float64(ns)/1e9)
	case d >= time.Millisecond:
		return fmt.Sprintf("%.2fms", float64(ns)/1e6)
	case d >= time.Microsecond:
		return fmt.Sprintf("%.2fµs", float64(ns)/1e3)
	default:
		return fmt.Sprintf("%.2fns", float64(ns))
	}
}

func formatDurationUs(us uint64) string {
	return formatDuration(time.Duration(us) * time.Microsecond)
}

// rustDebugDuration formats like Rust's {:?} for std::time::Duration.
func rustDebugDuration(d time.Duration) string {
	ns := d.Nanoseconds()
	format := func(intPart int64, frac int64, fracDigits int, unit string) string {
		if frac == 0 {
			return fmt.Sprintf("%d%s", intPart, unit)
		}
		fracStr := fmt.Sprintf("%0*d", fracDigits, frac)
		fracStr = strings.TrimRight(fracStr, "0")
		return fmt.Sprintf("%d.%s%s", intPart, fracStr, unit)
	}
	switch {
	case d >= time.Second:
		secs := ns / 1_000_000_000
		frac := ns % 1_000_000_000
		return format(secs, frac, 9, "s")
	case d >= time.Millisecond:
		ms := ns / 1_000_000
		frac := ns % 1_000_000
		return format(ms, frac, 6, "ms")
	case d >= time.Microsecond:
		us := ns / 1_000
		frac := ns % 1_000
		return format(us, frac, 3, "µs")
	default:
		return fmt.Sprintf("%dns", ns)
	}
}

// formatThroughputMbps formats bytes/sec as Mb/s with two decimals. For
// integer values it uses exact rationality so that the saturated value
// (u64::MAX from a zero duration) renders like the reference.
func formatThroughputMbps(bps uint64) string {
	// value = bps / 125000, rounded to 2 decimals.
	num := new(big.Int).SetUint64(bps)
	num.Mul(num, big.NewInt(100))
	den := big.NewInt(125000)
	q := new(big.Int)
	r := new(big.Int)
	q.QuoRem(num, den, r)
	// round half up
	twoR := new(big.Int).Mul(r, big.NewInt(2))
	if twoR.Cmp(den) >= 0 {
		q.Add(q, big.NewInt(1))
	}
	intPart := new(big.Int)
	frac := new(big.Int)
	intPart.QuoRem(q, big.NewInt(100), frac)
	return fmt.Sprintf("%s.%02d Mb/s", intPart.String(), frac.Int64())
}

func formatThroughputMbpsFloat(bps float64) string {
	if math.IsInf(bps, 0) || bps >= 1.8446744073709552e19 {
		return formatThroughputMbps(^uint64(0))
	}
	return fmt.Sprintf("%.2f Mb/s", bps/125000.0)
}

// ---- statistics collection ----

type streamDirKey struct {
	id     int64
	sender bool
}

type jsonIntervalData struct {
	streams []jsonStreamEntry
	sum     jsonSumEntry
}

type jsonFloat float64

func (f jsonFloat) MarshalJSON() ([]byte, error) {
	if f == 0 {
		return []byte("0.0"), nil
	}
	// Use a decimal (non-exponent) rendering.
	s := strings.TrimRight(strings.TrimRight(fmt.Sprintf("%.9F", float64(f)), "0"), ".")
	_ = s
	return json.Marshal(float64(f))
}

type jsonStreamEntry struct {
	ID            int64     `json:"id"`
	Start         jsonFloat `json:"start"`
	End           jsonFloat `json:"end"`
	Seconds       jsonFloat `json:"seconds"`
	Bytes         uint64    `json:"bytes"`
	BitsPerSecond jsonFloat `json:"bits_per_second"`
	Sender        bool      `json:"sender"`
}

type jsonSumEntry struct {
	Start         jsonFloat `json:"start"`
	End           jsonFloat `json:"end"`
	Seconds       jsonFloat `json:"seconds"`
	Bytes         uint64    `json:"bytes"`
	BitsPerSecond jsonFloat `json:"bits_per_second"`
	Sender        bool      `json:"sender"`
}

type jsonIntervalOut struct {
	Streams []jsonStreamEntry `json:"streams"`
	Sum     jsonSumEntry      `json:"sum"`
}

type statsCollector struct {
	start     time.Time
	startUnix int64

	mu              sync.Mutex
	requests        int64
	uploadDurUs     []uint64
	downloadDurUs   []uint64
	fblUs           []uint64
	uploadThrBps    []uint64
	downloadThrBps  []uint64
	intervalBytes   map[streamDirKey]uint64
	intervalOrder   []streamDirKey
	intervals       []jsonIntervalOut
}

func newStatsCollector() *statsCollector {
	now := time.Now()
	return &statsCollector{
		start:         now,
		startUnix:     now.Unix(),
		intervalBytes: map[streamDirKey]uint64{},
	}
}

func throughputBps(size uint64, durUs uint64) uint64 {
	if size == 0 {
		return 0
	}
	if durUs == 0 {
		return ^uint64(0)
	}
	// size * 1e6 / durUs, avoiding overflow with big ints for huge sizes.
	num := new(big.Int).SetUint64(size)
	num.Mul(num, big.NewInt(1_000_000))
	num.Quo(num, new(big.Int).SetUint64(durUs))
	if !num.IsUint64() {
		return ^uint64(0)
	}
	return num.Uint64()
}

func (s *statsCollector) recordUpload(size uint64, durUs uint64) {
	if size == 0 {
		return
	}
	s.mu.Lock()
	s.uploadDurUs = append(s.uploadDurUs, durUs)
	s.uploadThrBps = append(s.uploadThrBps, throughputBps(size, durUs))
	s.mu.Unlock()
}

func (s *statsCollector) recordDownload(size uint64, durUs uint64, fblUs uint64) {
	if size == 0 {
		return
	}
	s.mu.Lock()
	s.downloadDurUs = append(s.downloadDurUs, durUs)
	s.fblUs = append(s.fblUs, fblUs)
	s.downloadThrBps = append(s.downloadThrBps, throughputBps(size, durUs))
	s.requests++
	s.mu.Unlock()
}

func (s *statsCollector) registerStream(id int64, sender bool) {
	key := streamDirKey{id: id, sender: sender}
	s.mu.Lock()
	if _, ok := s.intervalBytes[key]; !ok {
		s.intervalBytes[key] = 0
		s.intervalOrder = append(s.intervalOrder, key)
	}
	s.mu.Unlock()
}

func (s *statsCollector) addBytes(id int64, sender bool, n uint64) {
	if n == 0 {
		return
	}
	key := streamDirKey{id: id, sender: sender}
	s.mu.Lock()
	if _, ok := s.intervalBytes[key]; !ok {
		s.intervalOrder = append(s.intervalOrder, key)
	}
	s.intervalBytes[key] += n
	s.mu.Unlock()
}

// drainInterval closes the current JSON interval [start,end] (seconds since
// the collector's start) and resets the per-interval byte counters.
func (s *statsCollector) drainInterval(startSec, endSec float64) {
	seconds := endSec - startSec
	s.mu.Lock()
	defer s.mu.Unlock()
	var streams []jsonStreamEntry
	if len(s.intervalOrder) > 0 {
		streams = make([]jsonStreamEntry, 0, len(s.intervalOrder))
	} else {
		streams = []jsonStreamEntry{}
	}
	var senderBytes, receiverBytes uint64
	hasSender := false
	for _, key := range s.intervalOrder {
		b := s.intervalBytes[key]
		var bps float64
		if seconds > 0 {
			bps = float64(b) * 8 / seconds
		}
		streams = append(streams, jsonStreamEntry{
			ID:            key.id,
			Start:         jsonFloat(startSec),
			End:           jsonFloat(endSec),
			Seconds:       jsonFloat(seconds),
			Bytes:         b,
			BitsPerSecond: jsonFloat(bps),
			Sender:        key.sender,
		})
		if key.sender {
			hasSender = true
			senderBytes += b
		} else {
			receiverBytes += b
		}
	}
	sumBytes := receiverBytes
	sumSender := false
	if hasSender {
		sumBytes = senderBytes
		sumSender = true
	}
	var sumBps float64
	if seconds > 0 {
		sumBps = float64(sumBytes) * 8 / seconds
	}
	s.intervals = append(s.intervals, jsonIntervalOut{
		Streams: streams,
		Sum: jsonSumEntry{
			Start:         jsonFloat(startSec),
