	// size * 1e6 / durUs, avoiding overflow with big ints for huge sizes.
	num := new(big.Int).SetUint64(size)
	num.Mul(num, big.NewInt(1_000_000))
	num.Quo(num, new(big.Int).SetUint64(durUs))
	if !num.IsUint64() {
		return ^uint64(0)
	}
	return num.Uint64()
}

func (s *statsCollector) recordUpload(size uint64, durUs uint64) {
	if size == 0 {
		return
	}
	s.mu.Lock()
	s.uploadDurUs = append(s.uploadDurUs, durUs)
	s.uploadThrBps = append(s.uploadThrBps, throughputBps(size, durUs))
	s.mu.Unlock()
}

func (s *statsCollector) recordDownload(size uint64, durUs uint64, fblUs uint64) {
	if size == 0 {
		return
	}
	s.mu.Lock()
	s.downloadDurUs = append(s.downloadDurUs, durUs)
	s.fblUs = append(s.fblUs, fblUs)
	s.downloadThrBps = append(s.downloadThrBps, throughputBps(size, durUs))
	s.requests++
	s.mu.Unlock()
}

func (s *statsCollector) registerStream(id int64, sender bool) {
	key := streamDirKey{id: id, sender: sender}
	s.mu.Lock()
	if _, ok := s.intervalBytes[key]; !ok {
		s.intervalBytes[key] = 0
		s.intervalOrder = append(s.intervalOrder, key)
	}
	s.mu.Unlock()
}

func (s *statsCollector) addBytes(id int64, sender bool, n uint64) {
	if n == 0 {
		return
	}
	key := streamDirKey{id: id, sender: sender}
	s.mu.Lock()
	if _, ok := s.intervalBytes[key]; !ok {
		s.intervalOrder = append(s.intervalOrder, key)
	}
	s.intervalBytes[key] += n
	s.mu.Unlock()
}

// drainInterval closes the current JSON interval [start,end] (seconds since
// the collector's start) and resets the per-interval byte counters.
func (s *statsCollector) drainInterval(startSec, endSec float64) {
	seconds := endSec - startSec
	s.mu.Lock()
	defer s.mu.Unlock()
	var streams []jsonStreamEntry
	if len(s.intervalOrder) > 0 {
		streams = make([]jsonStreamEntry, 0, len(s.intervalOrder))
	} else {
		streams = []jsonStreamEntry{}
	}
	var senderBytes, receiverBytes uint64
	hasSender := false
	for _, key := range s.intervalOrder {
		b := s.intervalBytes[key]
		var bps float64
		if seconds > 0 {
			bps = float64(b) * 8 / seconds
		}
		streams = append(streams, jsonStreamEntry{
			ID:            key.id,
			Start:         jsonFloat(startSec),
			End:           jsonFloat(endSec),
			Seconds:       jsonFloat(seconds),
			Bytes:         b,
			BitsPerSecond: jsonFloat(bps),
			Sender:        key.sender,
		})
		if key.sender {
			hasSender = true
			senderBytes += b
		} else {
			receiverBytes += b
		}
	}
	sumBytes := receiverBytes
	sumSender := false
	if hasSender {
		sumBytes = senderBytes
		sumSender = true
	}
	var sumBps float64
	if seconds > 0 {
		sumBps = float64(sumBytes) * 8 / seconds
	}
	s.intervals = append(s.intervals, jsonIntervalOut{
		Streams: streams,
		Sum: jsonSumEntry{
			Start:         jsonFloat(startSec),
			End:           jsonFloat(endSec),
			Seconds:       jsonFloat(seconds),
			Bytes:         sumBytes,
			BitsPerSecond: jsonFloat(sumBps),
			Sender:        sumSender,
		},
	})
	s.intervalBytes = map[streamDirKey]uint64{}
	s.intervalOrder = nil
}

func percentileU64(sorted []uint64, p int) uint64 {
	if len(sorted) == 0 {
		return 0
	}
	if p <= 0 {
		return sorted[0]
	}
	if p >= 100 {
		return sorted[len(sorted)-1]
	}
	// nearest-rank
	rank := (p*len(sorted) + 99) / 100
	if rank < 1 {
		rank = 1
	}
	if rank > len(sorted) {
		rank = len(sorted)
	}
	return sorted[rank-1]
}

func meanU64(vals []uint64) float64 {
	if len(vals) == 0 {
		return 0
	}
	var sum float64
	for _, v := range vals {
		sum += float64(v)
	}
	return sum / float64(len(vals))
}

type metricSnapshot struct {
	requests    int64
	uploadDur   []uint64
	downloadDur []uint64
	fbl         []uint64
	uploadThr   []uint64
	downloadThr []uint64
}

func (s *statsCollector) snapshot() metricSnapshot {
	s.mu.Lock()
	defer s.mu.Unlock()
	cp := func(in []uint64) []uint64 {
		out := append([]uint64(nil), in...)
		sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
		return out
	}
	return metricSnapshot{
		requests:    s.requests,
		uploadDur:   cp(s.uploadDurUs),
		downloadDur: cp(s.downloadDurUs),
		fbl:         cp(s.fblUs),
		uploadThr:   cp(s.uploadThrBps),
		downloadThr: cp(s.downloadThrBps),
	}
}

// renderTable renders one periodic report. elapsed is measured from the
// start of collection to the end of this reporting moment.
func (s *statsCollector) renderTable(elapsed time.Duration, connStatsLine string) string {
	snap := s.snapshot()
	var b strings.Builder
	elapsedSec := elapsed.Seconds()
	var rps float64
	if elapsedSec > 0 {
		rps = float64(snap.requests) / elapsedSec
	}
	b.WriteString("Overall stats:\n")
	b.WriteString(fmt.Sprintf("RPS: %.2f (%d requests in %s)\n", rps, snap.requests, formatDuration(elapsed)))
	b.WriteString("\nStream metrics:\n\n")
	b.WriteString("      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput\n")
	b.WriteString("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────\n")
	rows := []struct {
		label string
		p     int
		avg   bool
	}{
		{"AVG", 0, true},
		{"P0", 0, false},
		{"P10", 10, false},
		{"P50", 50, false},
		{"P90", 90, false},
		{"P100", 100, false},
	}
	for _, row := range rows {
		var upDur, downDur, fbl string
		var upThr, downThr string
		if row.avg {
			upDur = formatDurationUs(uint64(meanU64(snap.uploadDur)))
			downDur = formatDurationUs(uint64(meanU64(snap.downloadDur)))
			fbl = formatDurationUs(uint64(meanU64(snap.fbl)))
			upThr = formatThroughputMbpsFloat(meanU64(snap.uploadThr))
			downThr = formatThroughputMbpsFloat(meanU64(snap.downloadThr))
		} else {
			upDur = formatDurationUs(percentileU64(snap.uploadDur, row.p))
			downDur = formatDurationUs(percentileU64(snap.downloadDur, row.p))
			fbl = formatDurationUs(percentileU64(snap.fbl, row.p))
			upThr = formatThroughputMbps(percentileU64(snap.uploadThr, row.p))
			downThr = formatThroughputMbps(percentileU64(snap.downloadThr, row.p))
		}
		b.WriteString(fmt.Sprintf(" %-5s│ %15s │ %17s │ %10s │ %17s │ %18s\n", row.label, upDur, downDur, fbl, upThr, downThr))
	}
	b.WriteString("\n")
	if connStatsLine != "" {
		b.WriteString(connStatsLine)
		b.WriteString("\n\n")
	}
	return b.String()
}

// marshalJSON produces the iperf-style JSON document.
func (s *statsCollector) marshalJSON() []byte {
	s.mu.Lock()
	intervals := s.intervals
	s.mu.Unlock()
	if intervals == nil {
		intervals = []jsonIntervalOut{}
	}
	type timestamp struct {
		Timesecs int64 `json:"timesecs"`
	}
	type start struct {
		Timestamp timestamp `json:"timestamp"`
	}
	type doc struct {
		Start     start             `json:"start"`
		Intervals []jsonIntervalOut `json:"intervals"`
	}
	d := doc{Start: start{Timestamp: timestamp{Timesecs: s.startUnix}}, Intervals: intervals}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	// Encoder adds a trailing newline, which the reference does not.
	if err := enc.Encode(d); err != nil {
		return []byte("{}")
	}
	return bytes.TrimRight(buf.Bytes(), "\n")
}
