func clampWindow(v *uint64, def int64) int64 {
	if v == nil {
		return def
	}
	if *v == 0 {
		return -1
	}
	if *v > uint64(1<<63-1) {
		return 1<<63 - 1
	}
	return int64(*v)
}

func makeQUICConfig(common CommonOpts, tlsCfg *tls.Config, ql *qlogWriter) *quic.Config {
	cfg := &quic.Config{
		TLSConfig:                tlsCfg,
		MaxBidiRemoteStreams:     100,
		MaxUniRemoteStreams:      100,
		MaxStreamReadBufferSize:  clampWindow(common.StreamReceiveWindow, 1250000),
		MaxConnReadBufferSize:    clampWindow(common.ReceiveWindow, 6250000),
		MaxStreamWriteBufferSize: clampWindow(common.SendWindow, 1250000),
		HandshakeTimeout:         30 * time.Second,
	}
	if ql != nil {
		cfg.QLogLogger = ql.logger()
	}
	return cfg
}

func setAndCheckBuffers(conn *net.UDPConn, sendDesired, recvDesired uint64) {
	raw, err := conn.SyscallConn()
	if err != nil {
		return
	}
	apply := func(opt int, desired uint64) int {
		actual := -1
		_ = raw.Control(func(fd uintptr) {
			_ = syscall.SetsockoptInt(int(fd), syscall.SOL_SOCKET, opt, int(int32(desired)))
			v, err := syscall.GetsockoptInt(int(fd), syscall.SOL_SOCKET, opt)
			if err == nil {
				actual = v
			}
		})
		return actual
	}
	if actual := apply(syscall.SO_SNDBUF, sendDesired); actual >= 0 {
		if uint64(actual) < sendDesired || sendDesired > uint64(1<<63-1) {
			// The comparison in the reference is on unsigned sizes; a
			// negative-looking kernel value cannot happen for buffers.
			if int64(actual) >= 0 && uint64(actual) < sendDesired {
				logLine("perf", levelWarn, fmt.Sprintf("Unable to set desired send buffer size. Desired: %d, Actual: %d", sendDesired, actual))
			}
		}
	}
	if actual := apply(syscall.SO_RCVBUF, recvDesired); actual >= 0 {
		if int64(actual) >= 0 && uint64(actual) < recvDesired {
			logLine("perf", levelWarn, fmt.Sprintf("Unable to set desired recv buffer size. Desired: %d, Actual: %d", recvDesired, actual))
		}
	}
}

type endpointBundle struct {
	endpoint *quic.Endpoint
	udp      *net.UDPConn
	tracker  *endpointTracker
	local    netip.AddrPort
}

// makeEndpoint binds a UDP socket, applies buffer sizes (warning like the
// reference), validates the max UDP payload size, and creates an endpoint.
// For the client, listenCfg is nil.
func makeEndpoint(bind netip.AddrPort, common CommonOpts, listenCfg *quic.Config) (*endpointBundle, error) {
	udpAddr := &net.UDPAddr{IP: bind.Addr().AsSlice(), Port: int(bind.Port())}
	if bind.Addr().Zone() != "" {
		udpAddr.Zone = bind.Addr().Zone()
	}
	network := "udp"
	conn, err := net.ListenUDP(network, udpAddr)
	if err != nil {
		return nil, fmt.Errorf("binding endpoint: %s", rustOSError(err))
	}
	setAndCheckBuffers(conn, common.SendBufferSize, common.RecvBufferSize)
	if common.MaxUDPPayloadSize < 1200 || common.MaxUDPPayloadSize > 65527 {
		_ = conn.Close()
		return nil, fmt.Errorf("value exceeds supported bounds")
	}
	var pc net.PacketConn = conn
	var tracker *endpointTracker
	if common.ConnStats {
		tracker = &endpointTracker{}
		pc = &countingPacketConn{UDPConn: conn, tracker: tracker}
	}
	ep, err := quic.NewEndpoint(pc, listenCfg)
	if err != nil {
		_ = conn.Close()
		return nil, err
	}
	local := ep.LocalAddr()
	return &endpointBundle{endpoint: ep, udp: conn, tracker: tracker, local: local}, nil
}

func streamName(id int64) string {
	initiator := "client"
	if id&0x1 == 1 {
		initiator = "server"
	}
	dir := "bidirectional"
	if id&0x2 == 2 {
		dir = "unidirectional"
	}
	return fmt.Sprintf("%s %s stream %d", initiator, dir, id>>2)
}

