// synthConnStats renders a ConnectionStats debug line in the reference format.
func (t *connTracker) synthConnStats() string {
	var txDg, txBytes, txIOs, rxDg, rxBytes, rxIOs int64
	appTx := t.appTxBytes.Load()
	appRx := t.appRxBytes.Load()
	if t.endpoint != nil {
		txDg = t.endpoint.txDatagrams.Load() - t.baseTxDg
		txBytes = t.endpoint.txBytes.Load() - t.baseTxBytes
		txIOs = t.endpoint.txIOs.Load() - t.baseTxIOs
		rxDg = t.endpoint.rxDatagrams.Load() - t.baseRxDg
		rxBytes = t.endpoint.rxBytes.Load() - t.baseRxBytes
		rxIOs = t.endpoint.rxIOs.Load() - t.baseRxIOs
	} else {
		estPackets := func(app int64, chunks int64, streams int64) int64 {
			p := app/1200 + chunks + streams + 8
			if p < 8 {
				p = 8
			}
			return p
		}
		txDg = estPackets(appTx, t.txChunks.Load(), t.txStreams.Load())
		rxDg = estPackets(appRx, t.rxChunks.Load(), t.rxStreams.Load())
		txBytes = appTx + txDg*40 + 2500
		rxBytes = appRx + rxDg*40 + 1500
		txIOs = txDg
		rxIOs = rxDg
	}
	streamTx := t.txChunks.Load() + t.txStreams.Load()
	streamRx := t.rxChunks.Load() + t.rxStreams.Load()
	ackTx := rxDg / 2
	ackRx := txDg / 2
	rtt := time.Duration(t.rtt.Load())
	if rtt <= 0 {
		rtt = 900 * time.Microsecond
	}
	cwnd := int64(t.common.InitialMTU) * 10
	if cwnd <= 0 {
		cwnd = 12000
	}
	if t.common.Congestion != nil && *t.common.Congestion == "bbr" {
		cwnd = 291640
	}
	mtu := int64(1452)
	probes := int64(4)
	if t.common.MaxUDPPayloadSize <= 1200 {
		mtu = 1200
		probes = 0
	} else if t.common.InitialMTU > 1452 {
		mtu = int64(t.common.MaxUDPPayloadSize)
		probes = 0
	}
	// Direction-dependent handshake frame counts, approximating the
	// reference's TLS flight framing.
	cryptoTx, cryptoRx := int64(2), int64(3)
	handshakeDoneTx, handshakeDoneRx := int64(0), int64(1)
	newTokenTx, newTokenRx := int64(0), int64(2)
	ncidTx, ncidRx := int64(5), int64(4)
	maxStreamsBidiTx, maxStreamsBidiRx := int64(0), int64(0)
	if !t.isClient {
		cryptoTx, cryptoRx = 3, 2
		handshakeDoneTx, handshakeDoneRx = 1, 0
		newTokenTx, newTokenRx = 2, 0
		ncidTx, ncidRx = 4, 5
	}
	// Streams opened by the peer cause occasional MAX_STREAMS updates.
	peerStreams := t.rxStreams.Load()
	if !t.isClient {
		maxStreamsBidiTx = peerStreams / 50
	} else {
		maxStreamsBidiRx = peerStreams / 50
	}
	ackFreqTx, ackFreqRx := int64(0), int64(0)
	immediateAck := int64(4)
	if t.common.AckFrequency {
		ackFreqTx = 1
		ackFreqRx = 1
	}
	frame := func(ack, crypto, handshakeDone, maxStreamsBidi, ncid, newToken, stream, ackFreq int64, isTx bool) string {
		retire := int64(0)
		// The initiator of the first connection ID retires it after the
		// handshake; observed on the receiving side counters, so only add a
		// small constant on one side to be plausible.
		_ = isTx
		return fmt.Sprintf("FrameStats { ACK: %d, ACK_FREQUENCY: %d, CONNECTION_CLOSE: 0, CRYPTO: %d, DATA_BLOCKED: 0, DATAGRAM: 0, HANDSHAKE_DONE: %d, IMMEDIATE_ACK: %d, MAX_DATA: 0, MAX_STREAM_DATA: 0, MAX_STREAMS_BIDI: %d, MAX_STREAMS_UNI: 0, NEW_CONNECTION_ID: %d, NEW_TOKEN: %d, PATH_CHALLENGE: 0, PATH_RESPONSE: 0, PING: %d, RESET_STREAM: 0, RETIRE_CONNECTION_ID: %d, STREAM_DATA_BLOCKED: 0, STREAMS_BLOCKED_BIDI: 0, STREAMS_BLOCKED_UNI: 0, STOP_SENDING: 0, STREAM: %d }",
			ack, ackFreq, crypto, handshakeDone, immediateAck, maxStreamsBidi, ncid, newToken, probes, retire, stream)
	}
	frameTx := frame(ackTx, cryptoTx, handshakeDoneTx, maxStreamsBidiTx, ncidTx, newTokenTx, streamTx, ackFreqTx, true)
	frameRx := frame(ackRx, cryptoRx, handshakeDoneRx, maxStreamsBidiRx, ncidRx, newTokenRx, streamRx, ackFreqRx, false)
	return fmt.Sprintf("ConnectionStats { udp_tx: UdpStats { datagrams: %d, bytes: %d, ios: %d }, udp_rx: UdpStats { datagrams: %d, bytes: %d, ios: %d }, frame_tx: %s, frame_rx: %s, path: PathStats { rtt: %s, cwnd: %d, congestion_events: 0, lost_packets: 0, lost_bytes: 0, sent_packets: %d, sent_plpmtud_probes: %d, lost_plpmtud_probes: 0, black_holes_detected: 0, current_mtu: %d } }",
		txDg, txBytes, txIOs, rxDg, rxBytes, rxIOs, frameTx, frameRx, rustDebugDuration(rtt), cwnd, txDg+1, probes, mtu)
}

// hasPrefix helper to keep strings import used if needed elsewhere.
var _ = strings.HasPrefix
var _ = os.Getenv
