package main

import (
	"errors"
	"fmt"
	"io"
	"regexp"
	"strings"

	"golang.org/x/net/quic"
)

// connErrorPhrase maps a connection-final error from the QUIC library to
// the phrase the reference prints after "connection lost: ".
func connErrorPhrase(err error) string {
	if err == nil {
		return "closed"
	}
	var appErr *quic.ApplicationError
	if errors.As(err, &appErr) {
		return fmt.Sprintf("closed by peer: %s (code %d)", appErr.Reason, appErr.Code)
	}
	s := err.Error()
	ls := strings.ToLower(s)
	if strings.Contains(ls, "inactivity") || strings.Contains(ls, "idle") || strings.Contains(ls, "timed out") || strings.Contains(ls, "timeout") || strings.Contains(ls, "deadline") {
		return "timed out"
	}
	if m := regexp.MustCompile(`(?i)crypto_error\((\d+)\)`).FindStringSubmatch(s); m != nil {
		return fmt.Sprintf("aborted by peer: the cryptographic handshake failed: error %s", m[1])
	}
	if strings.Contains(s, "NO_ERROR") {
		return "aborted by peer: the connection is being closed abruptly in the absence of any error"
	}
	if strings.Contains(ls, "reset") {
		return "reset by peer"
	}
	if strings.Contains(ls, "closed connection") || strings.Contains(ls, "connection closed") {
		return "closed"
	}
	return "aborted by peer: " + s
}

// streamErrorCodeOf returns a peer stream error code, if present.
func streamErrorCodeOf(err error) (uint64, bool) {
	var code quic.StreamErrorCode
	if errors.As(err, &code) {
		return uint64(code), true
	}
	return 0, false
}

func isEOF(err error) bool {
	return errors.Is(err, io.EOF)
}
