	"context"
	"crypto/tls"
	"encoding/binary"
	"fmt"
	"io"
	"time"

	"golang.org/x/net/quic"
)

func runServer(opts *ServerOpts) error {
	// 1. Certificate (before anything else observable).
	var cert tls.Certificate
	var err error
	if opts.Key != nil && opts.Cert != nil {
		cert, err = loadServerCertificate(*opts.Key, *opts.Cert)
		if err != nil {
			return err
		}
	} else {
		cert, err = generateSelfSigned()
		if err != nil {
			return err
		}
	}

	// 2. Key logging file is created when building the crypto config.
	keylogFile := openKeylog(opts.Common.Keylog)
	if keylogFile != nil {
		defer keylogFile.Close()
	}

	// 3. qlog file.
	var ql *qlogWriter
	if opts.Common.Qlog != nil {
		ql, err = createQlog(*opts.Common.Qlog, true)
		if err != nil {
			return fmt.Errorf("%s", rustOSError(err))
		}
		defer ql.Close()
	}

	tlsCfg := &tls.Config{
		Certificates: []tls.Certificate{cert},
		NextProtos:   []string{"perf"},
		MinVersion:   tls.VersionTLS13,
	}
	if keylogFile != nil {
		tlsCfg.KeyLogWriter = keylogFile
	}
	quicCfg := makeQUICConfig(opts.Common, tlsCfg, ql)

	// 4. Bind endpoint.
	bundle, err := makeEndpoint(opts.Listen, opts.Common, quicCfg)
	if err != nil {
		return err
	}
	defer bundle.endpoint.Close(context.Background())

	logLine("perf::server", levelInfo, fmt.Sprintf("listening on %s", bundle.local.String()))

	for {
		conn, err := bundle.endpoint.Accept(context.Background())
		if err != nil {
			return err
		}
		tracker := newConnTracker(bundle.tracker, opts.Common, false)
		go handleServerConn(conn, opts, tracker)
	}
}

func handleServerConn(conn *quic.Conn, opts *ServerOpts, tracker *connTracker) {
	logLine("perf::server", levelDebug, fmt.Sprintf("%s connected", conn.RemoteAddr().String()))
	if opts.Common.ConnStats {
		go func() {
			ticker := time.NewTicker(2 * time.Second)
			defer ticker.Stop()
			for range ticker.C {
				printStdout(tracker.synthConnStats() + "\n\n")
			}
		}()
	}
	for {
		stream, err := conn.AcceptStream(context.Background())
		if err != nil {
			return
		}
		tracker.rxStreams.Add(1)
		go handleServerStream(conn, stream, tracker)
	}
}

func serverStreamFailed(err error, context string) {
	if context != "" {
		logLine("perf::server", levelError, fmt.Sprintf("request failed: %s: %s", context, err.Error()))
	} else {
		logLine("perf::server", levelError, fmt.Sprintf("request failed: %s", err.Error()))
	}
}

// classifyReadError converts a stream read error into the reference's phrase.
// It returns "" for a clean EOF.
func classifyReadError(err error, connDoneErr func() (error, bool)) error {
	if err == nil || isEOF(err) {
		return nil
	}
	if code, ok := streamErrorCodeOf(err); ok {
		return fmt.Errorf("stream reset by peer: error %d", code)
	}
	if cerr, done := connDoneErr(); done {
		return fmt.Errorf("connection lost: %s", connErrorPhrase(cerr))
	}
	return err
}

func handleServerStream(conn *quic.Conn, stream *quic.Stream, tracker *connTracker) {
	streamID := stream.ID()
	// Track the connection's terminal error for classification.
	connDone := make(chan struct{})
	var connErr error
	go func() {
		// Wait is also called by other stream handlers; that is fine.
		// Use a short poll through a dedicated waiter per stream would be
		// wasteful; instead call Wait which blocks until the connection ends.
		connErr = conn.Wait(context.Background())
		close(connDone)
	}()
	connDoneErr := func() (error, bool) {
		select {
		case <-connDone:
			return connErr, true
		default:
			return nil, false
		}
	}

	// Read the 8-byte big-endian download-size header.
	header := make([]byte, 8)
	read := 0
	for read < 8 {
		n, err := stream.Read(header[read:])
		if n > 0 {
			read += n
			tracker.appRxBytes.Add(int64(n))
		}
		if err != nil {
			if isEOF(err) {
				serverStreamFailed(fmt.Errorf("stream finished early (%d bytes read)", read), "reading request")
				return
			}
			if cerr := classifyReadError(err, connDoneErr); cerr != nil {
				serverStreamFailed(cerr, "reading request")
				return
			}
			serverStreamFailed(err, "reading request")
			return
		}
		if n == 0 {
			// Avoid a busy spin on a (should-not-happen) empty read.
			serverStreamFailed(fmt.Errorf("stream finished early (%d bytes read)", read), "reading request")
			return
		}
	}
	downloadSize := binary.BigEndian.Uint64(header)
	logLine("perf::server", levelDebug, fmt.Sprintf("got req for %d bytes on %s", downloadSize, streamName(streamID)))

	// Read and discard the upload until EOF.
	buf := make([]byte, 32768)
	for {
		n, err := stream.Read(buf)
		if n > 0 {
			tracker.appRxBytes.Add(int64(n))
			tracker.rxChunks.Add(1)
		}
		if err != nil {
			if isEOF(err) {
				break
			}
			if cerr := classifyReadError(err, connDoneErr); cerr != nil {
				serverStreamFailed(cerr, "")
				return
			}
			serverStreamFailed(err, "")
			return
		}
	}
	logLine("perf::server", levelDebug, fmt.Sprintf("finished reading %s", streamName(streamID)))

	// Prepare the response stream.
	var send *quic.Stream
	if stream.IsReadOnly() {
		ns, err := conn.NewSendOnlyStream(context.Background())
		if err != nil {
			if cerr := classifyReadError(err, connDoneErr); cerr != nil {
				serverStreamFailed(cerr, "sending response")
				return
			}
			serverStreamFailed(err, "sending response")
			return
		}
		send = ns
		tracker.txStreams.Add(1)
	} else {
		send = stream
	}

	// Write the response.
	remaining := downloadSize
	for remaining > 0 {
		chunk := remaining
		if chunk > uint64(len(fillerChunk)) {
			chunk = uint64(len(fillerChunk))
		}
		off := uint64(0)
		for off < chunk {
			n, err := send.Write(fillerChunk[off:chunk])
			if n > 0 {
				off += uint64(n)
				tracker.appTxBytes.Add(int64(n))
			}
			if err != nil {
				if code, ok := streamErrorCodeOf(err); ok {
					serverStreamFailed(fmt.Errorf("stream stopped by peer: error %d", code), "sending response")
					return
				}
				if cerr := classifyReadError(err, connDoneErr); cerr != nil {
					// classifyReadError phrases connection errors suitably.
					if cerr.Error() == err.Error() {
						serverStreamFailed(fmt.Errorf("connection lost: %s", connErrorPhrase(err)), "sending response")
					} else {
						serverStreamFailed(cerr, "sending response")
					}
					return
				}
				serverStreamFailed(err, "sending response")
				return
			}
			if n == 0 {
				serverStreamFailed(io.ErrUnexpectedEOF, "sending response")
				return
			}
		}
		tracker.txChunks.Add(1)
		remaining -= chunk
	}
	send.CloseWrite()
	logLine("perf::server", levelDebug, fmt.Sprintf("finished responding on %s", streamName(send.ID())))
}
EOF
gofmt -w errors_map.go server.go"}

