{"command":"cat > client.go <<'EOF'
package main

import (
	"context"
	"crypto/tls"
	"encoding/binary"
	"fmt"
	"net"
	"net/netip"
	"os"
	"os/signal"
	"strings"
	"sync"
	"time"

	"golang.org/x/net/quic"
)

// ---------- host resolution (Rust to_socket_addrs-like) ----------

func resolveHostRust(host string) (netip.AddrPort, error) {
	// Try a plain socket address first (matching std behaviour).
	if ap, err := parseSocketAddr(host); err == nil {
		return ap, nil
	}
	idx := strings.LastIndex(host, ":")
	if idx < 0 {
		return netip.AddrPort{}, fmt.Errorf("resolving host: invalid socket address")
	}
	hostPart := host[:idx]
	portStr := host[idx+1:]
	port, ok := parseRustPort(portStr)
	if !ok {
		return netip.AddrPort{}, fmt.Errorf("resolving host: invalid port value")
	}
	// Bracketed or bare IP host part.
	ipStr := hostPart
	if strings.HasPrefix(ipStr, "[") && strings.HasSuffix(ipStr, "]") {
		ipStr = ipStr[1 : len(ipStr)-1]
	}
	if ip, err := netip.ParseAddr(ipStr); err == nil {
		return netip.AddrPortFrom(ip.Unmap(), port), nil
	}
	ips, err := net.DefaultResolver.LookupIPAddr(context.Background(), hostPart)
	if err != nil || len(ips) == 0 {
		phrase := "Name or service not known"
		if err != nil {
			if de, ok := err.(*net.DNSError); ok {
				if de.IsTemporary || de.IsTimeout {
					phrase = "Temporary failure in name resolution"
				}
			} else if strings.Contains(strings.ToLower(err.Error()), "timeout") {
				phrase = "Temporary failure in name resolution"
			}
		}
		return netip.AddrPort{}, fmt.Errorf("resolving host: failed to lookup address information: %s", phrase)
	}
	return netip.AddrPortFrom(ips[0].IP, port), nil
}

func validServerName(s string) bool {
	if ip, err := netip.ParseAddr(s); err == nil && ip.Zone() == "" {
		return true
	}
	if s == "" || len(s) > 253 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] > 127 {
			return false
		}
	}
	name := s
	if strings.HasSuffix(name, ".") {
		name = name[:len(name)-1]
		if name == "" || strings.HasSuffix(name, ".") {
			return false
		}
	}
	labels := strings.Split(name, ".")
	for _, lab := range labels {
		if len(lab) == 0 || len(lab) > 63 {
			return false
		}
		if lab[0] == '-' || lab[len(lab)-1] == '-' {
			return false
		}
		for i := 0; i < len(lab); i++ {
			c := lab[i]
			ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_'
			if !ok {
				return false
			}
		}
	}
	// The final label must not be all-numeric.
	last := labels[len(labels)-1]
	allNum := true
	for i := 0; i < len(last); i++ {
		if last[i] < '0' || last[i] > '9' {
			allNum = false
			break
		}
	}
	if allNum {
		return false
	}
	return true
}

// ---------- client ----------

type clientRunner struct {
	opts    *ClientOpts
	conn    *quic.Conn
	watcher *connWatcher
	stats   *statsCollector
	tracker *connTracker
}

func runClient(opts *ClientOpts) error {
	// Parse port (first-colon segment) and server name.
	serverName := opts.Host
	var parsedPort *uint16
	if idx := strings.Index(opts.Host, ":"); idx >= 0 {
		serverName = opts.Host[:idx]
		rest := opts.Host[idx+1:]
		portStr := rest
		if j := strings.Index(rest, ":"); j >= 0 {
			portStr = rest[:j]
		}
		v, err := parseRustU64(portStr)
		if err != nil || v > 65535 {
			if err == nil {
				err = errTooLarge
			}
			return fmt.Errorf("parsing port: %s", err.Error())
		}
		p := uint16(v)
		parsedPort = &p
	}

	var remote netip.AddrPort
	if opts.IP != nil {
		port := uint16(443)
		if parsedPort != nil {
			port = *parsedPort
		}
		remote = netip.AddrPortFrom(*opts.IP, port)
	} else {
		ap, err := resolveHostRust(opts.Host)
		if err != nil {
			return err
		}
		remote = ap
	}

	var localAddr netip.AddrPort
	if opts.LocalAddr != nil {
		localAddr = *opts.LocalAddr
	} else if remote.Addr().Is4() || remote.Addr().Is4In6() {
		localAddr = netip.AddrPortFrom(netip.IPv4Unspecified(), 0)
	} else {
		localAddr = netip.AddrPortFrom(netip.IPv6Unspecified(), 0)
	}

	logLine("perf::client", levelInfo, fmt.Sprintf("connecting to %s at %s", serverName, remote.String()))
	logLine("perf::client", levelInfo, fmt.Sprintf("local addr %s", localAddr.String()))

	// Bind endpoint (validates max UDP payload size after warnings).
	bundle, err := makeEndpoint(localAddr, opts.Common, nil)
	if err != nil {
		return err
	}
	defer bundle.endpoint.Close(context.Background())

	// Crypto config / keylog (file created here).
	keylogFile := openKeylog(opts.Common.Keylog)
	if keylogFile != nil {
		defer keylogFile.Close()
	}

	// qlog file.
	var ql *qlogWriter
	if opts.Common.Qlog != nil {
		ql, err = createQlog(*opts.Common.Qlog, false)
		if err != nil {
			return fmt.Errorf("%s", rustOSError(err))
		}
		defer ql.Close()
	}

	// Validate the remote address and server name, in this order.
	if remote.Port() == 0 || remote.Addr().IsUnspecified() || (localAddr.Addr().Is4() && remote.Addr().Is6() && !remote.Addr().Is4In6()) {
		return fmt.Errorf("invalid remote address: %s", remote.String())
	}
	if !validServerName(serverName) {
		return fmt.Errorf("invalid server name: %s", serverName)
	}

	tlsCfg := &tls.Config{
		InsecureSkipVerify: true,
		NextProtos:         []string{"perf"},
		MinVersion:         tls.VersionTLS13,
		ServerName:         serverName,
	}
	if keylogFile != nil {
		tlsCfg.KeyLogWriter = keylogFile
	}
	quicCfg := makeQUICConfig(opts.Common, tlsCfg, ql)

	tracker := newConnTracker(bundle.tracker, opts.Common, true)
	dialStart := time.Now()
	conn, err := bundle.endpoint.Dial(context.Background(), "udp", remote.String(), quicCfg)
	if err != nil {
		return fmt.Errorf("connecting: %s", mapDialError(err))
	}
	tracker.noteRTT(time.Since(dialStart) / 2)
	watcher := watchConn(conn)
	logLine("perf::client", levelInfo, "established")

	stats := newStatsCollector()
	runner := &clientRunner{opts: opts, conn: conn, watcher: watcher, stats: stats, tracker: tracker}

	totalSlots := opts.BiRequests + opts.UniRequests
	if totalSlots == 0 {
		// With no request tasks the reference simply waits for the
		// connection to end (e.g. by idle timeout).
		<-watcher.done
		return writeJSONOutput(opts, stats)
	}

	var wg sync.WaitGroup
	var bi uint64
	for bi = 0; bi < opts.BiRequests; bi++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			runner.runBiLoop()
		}()
	}
	var uni uint64
	for uni = 0; uni < opts.UniRequests; uni++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			runner.runUniLoop()
		}()
	}

	// Stats reporting goroutine.
	stopStats := make(chan struct{})
	statsDone := make(chan struct{})
	go func() {
		defer close(statsDone)
		runner.statsLoop(stopStats)
	}()

	// Shutdown triggers: duration expiry, Ctrl-C, connection end, or all
	// runners finishing.
	runnersDone := make(chan struct{})
	go func() {
		wg.Wait()
		close(runnersDone)
	}()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt)
	defer signal.Stop(sigCh)

	var durationCh <-chan time.Time
	var timer *time.Timer
	// The reference's shutdown follows the nominal duration by roughly
	// 200ms while requests and interval reports keep running.
	timer = time.NewTimer(time.Duration(opts.Duration)*time.Second + 200*time.Millisecond)
	durationCh = timer.C
	defer timer.Stop()

	interrupted := false
	localShutdown := false
	select {
	case <-durationCh:
		localShutdown = true
	case <-sigCh:
		localShutdown = true
		interrupted = true
	case <-watcher.done:
		// Connection ended on its own (peer close / idle timeout).
	case <-runnersDone:
	}

	if localShutdown {
		logLine("perf::client", levelInfo, "shutting down")
		watcher.localClosing.Store(true)
		reason := "done"
		if interrupted {
			reason = "interrupted"
		}
		conn.Abort(&quic.ApplicationError{Code: 0, Reason: reason})
	}
	// Wait for the runners to observe the closure, bounded so a stalled
	// stream cannot hang the exit indefinitely.
	select {
	case <-runnersDone:
	case <-time.After(2 * time.Second):
	}
	close(stopStats)
	select {
	case <-statsDone:
	case <-time.After(time.Second):
	}
	// A short drain, mirroring the reference's pause before exit.
	time.Sleep(80 * time.Millisecond)
	_ = conn.Close()
	return writeJSONOutput(opts, stats)
}

func writeJSONOutput(opts *ClientOpts, stats *statsCollector) error {
	if opts.JSON == nil {
		return nil
	}
	data := stats.marshalJSON()
	if *opts.JSON == "-" {
		printStdout(string(data))
		return nil
	}
	if err := os.WriteFile(*opts.JSON, data, 0666); err != nil {
		return fmt.Errorf("%s", rustOSError(err))
	}
	return nil
}

func mapDialError(err error) string {
	if err == nil {
		return ""
	}
	s := err.Error()
	ls := strings.ToLower(s)
	if strings.Contains(ls, "deadline") || strings.Contains(ls, "handshake timeout") || strings.Contains(ls, "timed out") || strings.Contains(ls, "timeout") {
		return "timed out"
	}
	// TLS alert numbers surface as CRYPTO_ERROR(n) in transport errors, or
	// inside Go tls alert strings.
	if phrase := connErrorPhrase(err); strings.HasPrefix(phrase, "aborted by peer: the cryptographic") {
		return phrase
	}
	if strings.Contains(ls, "no application protocol") || strings.Contains(ls, "no_application_protocol") {
		return "aborted by peer: the cryptographic handshake failed: error 120"
	}
	if strings.Contains(ls, "alert") {
		// Best effort: extract a trailing alert description we know.
		return "aborted by peer: the cryptographic handshake failed: " + s
	}
	if p := connErrorPhrase(err); p != "" && p != "closed" {
		return p
	}
	return s
}

func (r *clientRunner) statsLoop(stop <-chan struct{}) {
	interval := time.Duration(r.opts.Interval) * time.Second
	intervalStart := r.stats.start
	next := time.Now().Add(interval)
	for {
		if interval > 0 {
			wait := time.Until(next)
			if wait < 0 {
				wait = 0
			}
			t := time.NewTimer(wait)
			select {
			case <-stop:
				t.Stop()
				return
			case <-t.C:
			}
		} else {
			select {
			case <-stop:
				return
			default:
			}
		}
		end := time.Now()
		r.stats.drainInterval(intervalStart.Sub(r.stats.start).Seconds(), end.Sub(r.stats.start).Seconds())
		elapsed := end.Sub(r.stats.start)
		connLine := ""
		if r.opts.Common.ConnStats {
			connLine = r.tracker.synthConnStats()
		}
		printStdout(r.stats.renderTable(elapsed, connLine))
		intervalStart = time.Now()
		next = intervalStart.Add(interval)
	}
}

// ---- request machinery ----

func (r *clientRunner) writeAll(stream *quic.Stream, data []byte, countStats bool) error {
	off := 0
	for off < len(data) {
		n, err := stream.Write(data[off:])
		if n > 0 {
			off += n
			r.tracker.appTxBytes.Add(int64(n))
			if countStats {
				r.stats.addBytes(stream.ID(), true, uint64(n))
			}
		}
		if err != nil {
			return err
		}
		if n == 0 {
			return fmt.Errorf("write returned 0")
		}
	}
	return nil
}

func (r *clientRunner) upload(stream *quic.Stream, size uint64) (uint64, error) {
	start := time.Now()
	if size > 0 {
		r.stats.registerStream(stream.ID(), true)
	}
	remaining := size
	for remaining > 0 {
		chunk := remaining
		if chunk > uint64(len(fillerChunk)) {
			chunk = uint64(len(fillerChunk))
		}
		if err := r.writeAll(stream, fillerChunk[:chunk], true); err != nil {
			return 0, err
		}
		r.tracker.txChunks.Add(1)
		remaining -= chunk
	}
	durUs := uint64(time.Since(start) / time.Microsecond)
	return durUs, nil
}

type downloadResult struct {
	durUs uint64
	fblUs uint64
	bytes uint64
}

func (r *clientRunner) download(stream *quic.Stream, register bool) (downloadResult, error) {
	start := time.Now()
	if register {
		r.stats.registerStream(stream.ID(), false)
	}
	buf := make([]byte, 32768)
	var firstAt time.Time
	var total uint64
	for {
		n, err := stream.Read(buf)
		if firstAt.IsZero() {
			firstAt = time.Now()
		}
		if n > 0 {
			total += uint64(n)
			r.tracker.appRxBytes.Add(int64(n))
			r.tracker.rxChunks.Add(1)
			if register {
				r.stats.addBytes(stream.ID(), false, uint64(n))
			}
		}
		if err != nil {
			if isEOF(err) {
				break
			}
			return downloadResult{bytes: total}, err
		}
	}
	end := time.Now()
	fbl := uint64(0)
	if !firstAt.IsZero() {
		fbl = uint64(firstAt.Sub(start) / time.Microsecond)
	}
	return downloadResult{durUs: uint64(end.Sub(start) / time.Microsecond), fblUs: fbl, bytes: total}, nil
}

func (r *clientRunner) classifyOpError(err error, isWrite bool) (string, bool) {
	// Returns (phrase, isConnectionLevel).
	if r.watcher.localClosing.Load() {
		return "connection lost: closed", true
	}
	if cerr, done := r.watcher.finalErr(); done {
		return "connection lost: " + connErrorPhrase(cerr), true
	}
	if code, ok := streamErrorCodeOf(err); ok {
		if isWrite {
			return fmt.Sprintf("stream stopped by peer: error %d", code), false
		}
		return fmt.Sprintf("stream reset by peer: error %d", code), false
	}
	// If the connection is already finished, treat as connection-level.
	if r.watcher.isDone() {
		cerr, _ := r.watcher.finalErr()
		return "connection lost: " + connErrorPhrase(cerr), true
	}
	s := err.Error()
	if strings.Contains(strings.ToLower(s), "connection") || strings.Contains(strings.ToLower(s), "closed") {
		// Could be stream closed; keep the raw phrase short.
		if strings.Contains(strings.ToLower(s), "stream") {
			return s, false
		}
		return "connection lost: closed", true
	}
	return s, false
}

func (r *clientRunner) doBiRequest() error {
	stream, err := r.conn.NewStream(context.Background())
	if err != nil {
		return err
	}
	r.tracker.txStreams.Add(1)
	logLine("perf::client", levelDebug, fmt.Sprintf("sending request on %s", streamName(stream.ID())))

	header := make([]byte, 8)
	binary.BigEndian.PutUint64(header, r.opts.DownloadSize)
	uploadStart := time.Now()
	if err := r.writeAll(stream, header, false); err != nil {
		return err
	}
	var uploadDurUs uint64
	if r.opts.UploadSize > 0 {
		d, err := r.upload(stream, r.opts.UploadSize)
		if err != nil {
			return err
		}
		// Include the header write in the upload duration measurement
		// window approximately by measuring from just before it.
		uploadDurUs = uint64(time.Since(uploadStart) / time.Microsecond)
		_ = d
		stream.CloseWrite()
		r.stats.recordUpload(r.opts.UploadSize, uploadDurUs)
		logLine("perf::client", levelDebug, fmt.Sprintf("upload finished on %s", streamName(stream.ID())))
	} else {
		stream.CloseWrite()
	}
	if r.opts.DownloadSize > 0 {
		res, err := r.download(stream, true)
		if err != nil {
			return err
		}
		r.stats.recordDownload(r.opts.DownloadSize, res.durUs, res.fblUs)
		logLine("perf::client", levelDebug, fmt.Sprintf("response finished on %s", streamName(stream.ID())))
	} else {
		stream.CloseRead()
	}
	return nil
}

func (r *clientRunner) runBiLoop() {
	for {
		err := r.doBiRequest()
		if err == nil {
			if r.watcher.isDone() || r.watcher.localClosing.Load() {
				return
			}
			continue
		}
		phrase, isConn := r.classifyOpError(err, false)
		logLine("perf::client", levelError, fmt.Sprintf("request failed: %s", phrase))
		if isConn {
			return
		}
		if r.watcher.isDone() || r.watcher.localClosing.Load() {
			return
		}
	}
}

func (r *clientRunner) doUniRequest() error {
	stream, err := r.conn.NewSendOnlyStream(context.Background())
	if err != nil {
		return err
	}
	r.tracker.txStreams.Add(1)
	logLine("perf::client", levelDebug, fmt.Sprintf("sending request on %s", streamName(stream.ID())))
	header := make([]byte, 8)
	binary.BigEndian.PutUint64(header, r.opts.DownloadSize)
	uploadStart := time.Now()
	if err := r.writeAll(stream, header, false); err != nil {
		return err
	}
	if r.opts.UploadSize > 0 {
		if _, err := r.upload(stream, r.opts.UploadSize); err != nil {
			return err
		}
		uploadDurUs := uint64(time.Since(uploadStart) / time.Microsecond)
		stream.CloseWrite()
		r.stats.recordUpload(r.opts.UploadSize, uploadDurUs)
		logLine("perf::client", levelDebug, fmt.Sprintf("upload finished on %s", streamName(stream.ID())))
	} else {
		stream.CloseWrite()
	}

	// Consume the server's unidirectional response stream. This wait is
	// what paces a unidirectional request slot, as in the reference.
	resp, err := r.conn.AcceptStream(context.Background())
	if err != nil {
		return err
	}
	r.tracker.rxStreams.Add(1)
	if r.opts.DownloadSize > 0 {
		res, err := r.download(resp, true)
		if err != nil {
			return err
		}
		r.stats.recordDownload(r.opts.DownloadSize, res.durUs, res.fblUs)
		logLine("perf::client", levelDebug, fmt.Sprintf("response finished on %s", streamName(resp.ID())))
	} else {
		// Drain without recording download metrics.
		if _, err := r.download(resp, false); err != nil {
			return err
		}
	}
	return nil
}

func (r *clientRunner) runUniLoop() {
	for {
		err := r.doUniRequest()
		if err == nil {
			if r.watcher.isDone() || r.watcher.localClosing.Load() {
				return
			}
			continue
		}
		if r.watcher.localClosing.Load() {
			logLine("perf::client", levelError, "sending request failed: closed")
			return
		}
		if r.watcher.isDone() {
			// Peer-initiated connection end: the reference's uni senders
			// exit quietly in this case.
			return
		}
		phrase, isConn := r.classifyOpError(err, true)
		_ = phrase
		logLine("perf::client", levelError, "sending request failed: closed")
		if isConn {
			return
		}
	}
}
