package main

import (
	"fmt"
	"reflect"
	"unsafe"

	"golang.org/x/net/quic"
)

// streamOutDone returns the stream's internal "all writes acknowledged"
// channel. The public API only exposes this wait through Stream.Close,
// which also closes the read side — unsuitable for a bidirectional
// request/response exchange. Accessing it lets the upload phase end when
// the peer has acknowledged the data, matching the reference's semantics.
// It is best-effort: if the field is unavailable, callers proceed without
// the extra wait.
func streamOutDone(s *quic.Stream) (chan struct{}, bool) {
	v := reflect.ValueOf(s)
	if v.Kind() != reflect.Pointer || v.IsNil() {
		return nil, false
	}
	f := v.Elem().FieldByName("outdone")
	if !f.IsValid() {
		return nil, false
	}
	defer func() { _ = recover() }()
	ptr := unsafe.Pointer(f.UnsafeAddr())
	ch := reflect.NewAt(f.Type(), ptr).Elem().Interface()
	out, ok := ch.(chan struct{})
	if !ok || out == nil {
		return nil, false
	}
	return out, true
}

func (r *clientRunner) waitUploadAcked(stream *quic.Stream) error {
	ch, ok := streamOutDone(stream)
	if !ok {
		return nil
	}
	select {
	case <-ch:
		return nil
	case <-r.watcher.done:
		return fmt.Errorf("connection closed while waiting for acknowledgement")
	}
}
