def jaro(a,b):
 if a==b:return 1
 la,lb=len(a),len(b); md=max(la,lb)//2-1
 am=[0]*la; bm=[0]*lb; m=0
 for i in range(la):
  for j in range(max(0,i-md), min(i+md+1,lb)):
   if not bm[j] and a[i]==b[j]: am[i]=bm[j]=1;m+=1;break
 if m==0:return 0
 t=0;k=0
 for i in range(la):
  if am[i]:
   while not bm[k]:k+=1
   if a[i]!=b[k]:t+=1
   k+=1
 return (m/la+m/lb+(m-t/2)/m)/3
def jw(a,b):
 j=jaro(a,b); p=0
 while p<min(4,len(a),len(b)) and a[p]==b[p]:p+=1
 return j+p*0.1*(1-j)
for a,b in [("duretion","congestion"),("ser","server"),("dur","duration"),("list","listen"),("congeston","congestion")]:print(a,b,jaro(a,b),jw(a,b))
PY"}

